import{_ as a,o as r,c as t,ag as s}from"./chunks/framework.DEqXEGcv.js";const o="/images/issues/033/cover-bridge.jpg",i="/images/issues/033/theme-code-review.jpg",n="/images/issues/033/theme-containers.jpg",l="/images/issues/033/theme-pipeline.jpg",c="/images/issues/033/news-copilot.jpg",h="/images/issues/033/news-scorecard.jpg",g="/images/issues/033/news-reproducible.jpg",p="/images/issues/033/world-jinping.jpg",d="/images/issues/033/world-angel.jpg",u="/images/issues/033/world-global-center.jpg",m="/images/issues/033/world-qinling.jpg",b="/images/issues/033/world-cables.jpg",_="/images/issues/033/tool-scorecard.jpg",f="/images/issues/033/tool-cosign.jpg",q="/images/issues/033/tool-syft.jpg",k="/images/issues/033/tool-dagger.jpg",x="/images/issues/033/recommend-mars.jpg",I=JSON.parse('{"title":"小七的周刊（第 033 期）：会验证的自动化，才值得交出权限","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"小七的周刊（第 033 期）：会验证的自动化，才值得交出权限"}],["meta",{"property":"og:description","content":"从 AI coding agent、软件供应链到可复现构建，讨论自动化如何留下可检查的证据。"}],["meta",{"property":"og:image","content":"/images/issues/033/cover-bridge.jpg"}],["meta",{"property":"og:image:alt","content":"第 033 期封面图：跨越峡谷的桥梁"}],["meta",{"property":"og:url","content":"https://blog.leeseven.com/issues/issue-033"}]]},"headers":[],"relativePath":"issues/issue-033.md","filePath":"issues/issue-033.md","lastUpdated":1792364584000}'),P={name:"issues/issue-033.md"};function S(j,e,w,y,v,A){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="小七的周刊-第-033-期-会验证的自动化-才值得交出权限" tabindex="-1">小七的周刊（第 033 期）：会验证的自动化，才值得交出权限 <a class="header-anchor" href="#小七的周刊-第-033-期-会验证的自动化-才值得交出权限" aria-label="Permalink to &quot;小七的周刊（第 033 期）：会验证的自动化，才值得交出权限&quot;">​</a></h1><p><em>这里记录每周值得分享的科技内容，<strong>每周一发布</strong>（北京时间 07:00）。</em></p><h2 id="本期-3-个要点" tabindex="-1">本期 3 个要点 <a class="header-anchor" href="#本期-3-个要点" aria-label="Permalink to &quot;本期 3 个要点&quot;">​</a></h2><ol><li><strong>自动化的核心从执行变成证明</strong>：能完成任务只是起点，还要能说明改了什么、为什么这样改、如何撤销。</li><li><strong>AI coding agent 需要更窄的权限</strong>：沙箱、测试和差异审查，比一句“请放心”更可靠。</li><li><strong>供应链证据要进入日常开发</strong>：锁文件、构建来源和签名不能只在事故之后才补。</li></ol><h2 id="封面图" tabindex="-1">封面图 <a class="header-anchor" href="#封面图" aria-label="Permalink to &quot;封面图&quot;">​</a></h2><p><img src="'+o+'" alt="跨越峡谷的桥梁"></p><p>封面图：跨越峡谷的桥梁。自动化把距离缩短，但桥面下仍需要可检查的结构和维护记录。</p><h2 id="本周短谈" tabindex="-1">本周短谈 <a class="header-anchor" href="#本周短谈" aria-label="Permalink to &quot;本周短谈&quot;">​</a></h2><h3 id="_1-agent-的第一生产力是差异-而不是速度" tabindex="-1">1. Agent 的第一生产力是差异，而不是速度 <a class="header-anchor" href="#_1-agent-的第一生产力是差异-而不是速度" aria-label="Permalink to &quot;1. Agent 的第一生产力是差异，而不是速度&quot;">​</a></h3><p><img src="'+i+'" alt="代码审查界面"></p><p>AI coding agent 最容易展示的是“几分钟写出一个功能”，最容易被忽略的是它到底改动了哪些文件。对真实项目而言，可审查的 diff、通过的测试和明确的回滚点，比一次漂亮的演示更重要。把任务拆成小提交，让 agent 先解释计划，再限制它只能访问工作区和测试环境，开发者获得的是更稳定的交付边界。小团队也能做到：从禁止直接推生产、要求保留测试日志开始。</p><h3 id="_2-沙箱不是不信任工具-而是承认工具会犯错" tabindex="-1">2. 沙箱不是不信任工具，而是承认工具会犯错 <a class="header-anchor" href="#_2-沙箱不是不信任工具-而是承认工具会犯错" aria-label="Permalink to &quot;2. 沙箱不是不信任工具，而是承认工具会犯错&quot;">​</a></h3><p><img src="'+n+'" alt="隔离的集装箱码头"></p><p>容器、临时凭证和最小文件权限，构成了 agent 的基本活动范围。它们不能消除提示注入或依赖漏洞，却能把一次错误从“全机事故”缩小为“一个可删除的工作目录”。边界在于，沙箱配置本身也要测试：网络是否真的受限，密钥是否会出现在日志，失败后资源是否会清理。自动化越强，权限越应该短、窄、可撤销。</p><h3 id="_3-可复现构建让-我这里能跑-变成可验证事实" tabindex="-1">3. 可复现构建让“我这里能跑”变成可验证事实 <a class="header-anchor" href="#_3-可复现构建让-我这里能跑-变成可验证事实" aria-label="Permalink to &quot;3. 可复现构建让“我这里能跑”变成可验证事实&quot;">​</a></h3><p><img src="'+l+'" alt="流水线与仓库"></p><p>锁定依赖版本只是第一步。构建环境、工具链版本、输入源码和产物摘要都被记录后，团队才有机会回答“这个二进制从哪里来”。对应用团队而言，不必先追求百分之百复现；先找出一个关键发布物，记录输入和摘要，再把差异纳入构建失败报告，会比增加一页合规文档更有用。</p><h2 id="科技与-ai-动态" tabindex="-1">科技与 AI 动态 <a class="header-anchor" href="#科技与-ai-动态" aria-label="Permalink to &quot;科技与 AI 动态&quot;">​</a></h2><h3 id="_1-github-copilot-coding-agent-把任务交给异步工作流" tabindex="-1">1. <a href="https://github.blog/news-insights/product-news/github-copilot-coding-agent/" target="_blank" rel="noreferrer">GitHub Copilot coding agent 把任务交给异步工作流</a> <a class="header-anchor" href="#_1-github-copilot-coding-agent-把任务交给异步工作流" aria-label="Permalink to &quot;1. [GitHub Copilot coding agent 把任务交给异步工作流](https://github.blog/news-insights/product-news/github-copilot-coding-agent/)&quot;">​</a></h3><p><img src="'+c+'" alt="代码托管与自动化工作流"></p><p>【事实】GitHub 将 coding agent 放进 issue、分支和 pull request 工作流，让 agent 可以在隔离环境中完成任务并提交变更。它把问答式辅助推进到可审查的异步协作，但权限、测试和人工合并仍是关键环节。</p><p>【推测】竞争力不会只看生成速度，而会看它能否稳定地产出小而清楚的变更。建议从低风险维护任务试点，并把人工审查设为默认。</p><h3 id="_2-openssf-scorecard-为开源依赖提供可重复检查" tabindex="-1">2. <a href="https://github.com/ossf/scorecard" target="_blank" rel="noreferrer">OpenSSF Scorecard 为开源依赖提供可重复检查</a> <a class="header-anchor" href="#_2-openssf-scorecard-为开源依赖提供可重复检查" aria-label="Permalink to &quot;2. [OpenSSF Scorecard 为开源依赖提供可重复检查](https://github.com/ossf/scorecard)&quot;">​</a></h3><p><img src="'+h+'" alt="依赖检查报告"></p><p>【事实】Scorecard 检查分支保护、危险工作流、依赖更新等维护信号，帮助使用者在引入依赖前获得一组可比较的指标。它不是安全证明，也不能替代代码审查。</p><p>【推测】低分应该触发人工判断，而不是自动宣布项目不可信；否则容易把维护良好但规模较小的项目误伤。</p><h3 id="_3-reproducible-builds-让软件产物可以被重新计算" tabindex="-1">3. <a href="https://reproducible-builds.org/" target="_blank" rel="noreferrer">Reproducible Builds 让软件产物可以被重新计算</a> <a class="header-anchor" href="#_3-reproducible-builds-让软件产物可以被重新计算" aria-label="Permalink to &quot;3. [Reproducible Builds 让软件产物可以被重新计算](https://reproducible-builds.org/)&quot;">​</a></h3><p><img src="'+g+'" alt="可重复的构建产物"></p><p>【事实】可复现构建推动不同环境对相同源码生成一致产物，从而让用户检查发布包是否真的来自声明的源码。时间戳、路径和非确定性工具链都是常见障碍。</p><p>【推测】先找出一个关键发布物，记录输入和摘要，再把差异纳入构建报告，会比增加一页合规文档更有用。</p><h2 id="世界之最" tabindex="-1">世界之最 <a class="header-anchor" href="#世界之最" aria-label="Permalink to &quot;世界之最&quot;">​</a></h2><h3 id="_1-世界最深的地下实验室-锦屏地下实验室" tabindex="-1">1. 世界最深的地下实验室：锦屏地下实验室 <a class="header-anchor" href="#_1-世界最深的地下实验室-锦屏地下实验室" aria-label="Permalink to &quot;1. 世界最深的地下实验室：锦屏地下实验室&quot;">​</a></h3><p><img src="'+p+'" alt="港珠澳大桥"><em>锦屏地下实验室位于深山之中，为低噪声实验提供屏蔽。</em> 超长工程依赖分层监测和持续维护。软件平台也一样，接口处的证据比单个模块的峰值性能更重要。</p><h3 id="_2-世界最高的瀑布-委内瑞拉安赫尔瀑布" tabindex="-1">2. 世界最高的瀑布：委内瑞拉安赫尔瀑布 <a class="header-anchor" href="#_2-世界最高的瀑布-委内瑞拉安赫尔瀑布" aria-label="Permalink to &quot;2. 世界最高的瀑布：委内瑞拉安赫尔瀑布&quot;">​</a></h3><p><img src="'+d+'" alt="安赫尔瀑布"><em>安赫尔瀑布落差约 979 米。</em> 极端高度带来风和水量变化。系统遇到峰值流量时，也要提前设计降级路径，而不是只在晴天测性能。</p><h3 id="_3-世界最大的单体建筑-新世纪环球中心" tabindex="-1">3. 世界最大的单体建筑：新世纪环球中心 <a class="header-anchor" href="#_3-世界最大的单体建筑-新世纪环球中心" aria-label="Permalink to &quot;3. 世界最大的单体建筑：新世纪环球中心&quot;">​</a></h3><p><img src="'+u+'" alt="新世纪环球中心"><em>成都新世纪环球中心，以巨大室内空间著称。</em> 规模增长会制造管理复杂度。组织和代码库都需要边界、索引与可观测性，否则更大只是更难找。</p><h3 id="_4-世界最长的公路隧道-秦岭终南山隧道" tabindex="-1">4. 世界最长的公路隧道：秦岭终南山隧道 <a class="header-anchor" href="#_4-世界最长的公路隧道-秦岭终南山隧道" aria-label="Permalink to &quot;4. 世界最长的公路隧道：秦岭终南山隧道&quot;">​</a></h3><p><img src="'+m+'" alt="青函隧道"><em>秦岭终南山隧道穿越中国秦岭山脉。</em> 看不见的基础设施更需要检测和冗余。依赖、构建步骤和权限同样藏在系统底部，不能因为用户看不到就不记录。</p><h3 id="_5-世界最大的水下观测网-海底电缆系统" tabindex="-1">5. 世界最大的水下观测网：海底电缆系统 <a class="header-anchor" href="#_5-世界最大的水下观测网-海底电缆系统" aria-label="Permalink to &quot;5. 世界最大的水下观测网：海底电缆系统&quot;">​</a></h3><p><img src="'+b+'" alt="中国天眼 FAST"><em>海底电缆系统承载跨洲通信和全球数据流。</em> 网络越关键，冗余和故障切换越重要。日志和告警也要先定义信号，再增加采集量。</p><h2 id="工具深挖" tabindex="-1">工具深挖 <a class="header-anchor" href="#工具深挖" aria-label="Permalink to &quot;工具深挖&quot;">​</a></h2><h3 id="_1-openssf-scorecard-给依赖做一次可解释体检" tabindex="-1">1. <a href="https://github.com/ossf/scorecard" target="_blank" rel="noreferrer">OpenSSF Scorecard：给依赖做一次可解释体检</a> <a class="header-anchor" href="#_1-openssf-scorecard-给依赖做一次可解释体检" aria-label="Permalink to &quot;1. [OpenSSF Scorecard：给依赖做一次可解释体检](https://github.com/ossf/scorecard)&quot;">​</a></h3><p><img src="'+_+'" alt="Scorecard 仓库页面"> Scorecard 适合在引入依赖时做第一轮检查，尤其能提醒团队注意工作流权限、分支保护和依赖更新。它不适合被当成安全分数排行榜，低分应该触发人工判断。</p><h3 id="_2-cosign-把签名接入容器发布" tabindex="-1">2. <a href="https://github.com/sigstore/cosign" target="_blank" rel="noreferrer">Cosign：把签名接入容器发布</a> <a class="header-anchor" href="#_2-cosign-把签名接入容器发布" aria-label="Permalink to &quot;2. [Cosign：把签名接入容器发布](https://github.com/sigstore/cosign)&quot;">​</a></h3><p><img src="'+f+'" alt="Cosign 命令行工具"> Cosign 为容器和其他制品提供签名与验证能力。先签名一个发布镜像、在部署前验证，再扩展到更多制品，通常比一次性改造全部流水线更容易维护。</p><h3 id="_3-syft-生成软件物料清单" tabindex="-1">3. <a href="https://github.com/anchore/syft" target="_blank" rel="noreferrer">Syft：生成软件物料清单</a> <a class="header-anchor" href="#_3-syft-生成软件物料清单" aria-label="Permalink to &quot;3. [Syft：生成软件物料清单](https://github.com/anchore/syft)&quot;">​</a></h3><p><img src="'+q+'" alt="软件物料清单"> Syft 能从镜像和文件系统生成 SBOM，让漏洞响应从猜测依赖变成查询清单，适合放在构建阶段保存产物。</p><h3 id="_4-dagger-用代码组织可移植流水线" tabindex="-1">4. <a href="https://dagger.io/" target="_blank" rel="noreferrer">Dagger：用代码组织可移植流水线</a> <a class="header-anchor" href="#_4-dagger-用代码组织可移植流水线" aria-label="Permalink to &quot;4. [Dagger：用代码组织可移植流水线](https://dagger.io/)&quot;">​</a></h3><p><img src="'+k+'" alt="Dagger 流水线"> Dagger 用容器化方式描述 CI 步骤，适合需要在本地和远程复用同一套构建逻辑的团队。没有跨环境痛点的小项目，直接使用现有 CI 配置可能更轻。</p><h2 id="本周冷知识-彩蛋" tabindex="-1">本周冷知识 / 彩蛋 <a class="header-anchor" href="#本周冷知识-彩蛋" aria-label="Permalink to &quot;本周冷知识 / 彩蛋&quot;">​</a></h2><ul><li>🥚 <strong>冷知识</strong>：SBOM 借用了制造业的 BOM，核心思想是知道产品由哪些部件组成。</li><li>🧠 <strong>彩蛋</strong>：哈希值不是加密，也不能证明内容安全；它更像文件指纹，适合检查内容是否被替换。</li></ul><h2 id="小七的碎碎念" tabindex="-1">小七的碎碎念 <a class="header-anchor" href="#小七的碎碎念" aria-label="Permalink to &quot;小七的碎碎念&quot;">​</a></h2><p>我现在看到“全自动发布”时，第一反应还是找差异、找日志、找撤销按钮。速度很迷人，但能把过程讲清楚的系统，才真的让人敢把下一步交出去。</p><h2 id="意外推荐-非科技" tabindex="-1">意外推荐（非科技） <a class="header-anchor" href="#意外推荐-非科技" aria-label="Permalink to &quot;意外推荐（非科技）&quot;">​</a></h2><p><strong>《火星救援》</strong>（小说）</p><p><img src="'+x+'" alt="火星救援书影"><em>《火星救援》讲的不是天才一闪，而是把问题拆小、记录清楚、逐项验证。</em></p><p>它最迷人的地方是工程细节：每一个自救方案都要经过计算、试验和失败复盘。对软件工作者来说，这比灵光一现解决一切更接近真实世界。</p><h2 id="互动钩子" tabindex="-1">互动钩子 <a class="header-anchor" href="#互动钩子" aria-label="Permalink to &quot;互动钩子&quot;">​</a></h2><blockquote><p><strong>本周问题：你愿意让 coding agent 自动合并哪一种低风险改动？又会为它保留哪一道人工检查？</strong></p></blockquote><h2 id="本周行动清单" tabindex="-1">本周行动清单 <a class="header-anchor" href="#本周行动清单" aria-label="Permalink to &quot;本周行动清单&quot;">​</a></h2><ul><li>[ ] 为一个 agent 任务限制文件范围、网络访问和凭证寿命。</li><li>[ ] 给一次发布保存源码版本、依赖清单和产物摘要。</li><li>[ ] 在 CI 中为一个容器生成 SBOM，并把它和发布物关联。</li><li>[ ] 选一个低风险 issue，让 agent 提交小型 pull request，人工检查 diff 与测试。</li></ul><div class="issue-subscribe-cta"><h3 id="📬-喜欢这期内容" tabindex="-1">📬 喜欢这期内容？ <a class="header-anchor" href="#📬-喜欢这期内容" aria-label="Permalink to &quot;📬 喜欢这期内容？&quot;">​</a></h3><p>订阅「小七的周刊」，每周一收到最新一期。</p><div class="issue-cta-buttons"><a href="/feed.xml" class="cta-rss" target="_blank" rel="noopener noreferrer">RSS 订阅</a><a href="https://github.com/leeseven1211/blog-weekly" class="cta-share" target="_blank" rel="noopener noreferrer">GitHub</a></div></div>',63)])])}const O=a(P,[["render",S]]);export{I as __pageData,O as default};
